// Custom Worker entry: wraps the OpenNext-generated handler and adds the cron `scheduled`
// handler that replaces vercel.json "crons". Each cron calls the same Next route Vercel hit,
// with the CRON_SECRET bearer, through the in-process handler (no network round-trip).
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

// cron expression (must match wrangler.jsonc triggers.crons) -> route
const CRONS: Record<string, string> = {
  "0 9 * * *": "/api/cron/reminders",
};

type Env = { CRON_SECRET?: string; CRON_BASE_URL?: string; CRONS_ENABLED?: string } & Record<string, unknown>;

export default {
  fetch: handler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    // Vercel's cron keeps running until cutover; running both would double the side effects.
    // Off unless CRONS_ENABLED="true" (flip it at cutover).
    if (env.CRONS_ENABLED !== "true") {
      console.log(`cron ${controller.cron} skipped (CRONS_ENABLED != "true")`);
      return;
    }
    const path = CRONS[controller.cron];
    if (!path) {
      console.error(`no route for cron "${controller.cron}"`);
      return;
    }
    const base = env.CRON_BASE_URL || "https://openprop.wrapit.workers.dev";
    const req = new Request(new URL(path, base), {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}`, "user-agent": "cloudflare-cron" },
    });
    const res: Response = await handler.fetch(req, env, ctx);
    console.log(`cron ${controller.cron} ${path} -> ${res.status} ${(await res.text()).slice(0, 500)}`);
  },
} satisfies ExportedHandler<Env>;

// @ts-ignore re-export Durable Objects OpenNext may generate (harmless if unused)
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
